/**
 * Ghamdan (GTS) website rebuild — shared data types.
 *
 * Sources: ghamdan-product-catalogue.xlsx (via old build assets/js/data.js,
 * generated by tools/extract_catalog.py), old build assets/js/settings.js,
 * and old build tools/sitegen/content.py + per-page GTS_PAGE_I18N JSON.
 *
 * Rules carried over from the sources (do not weaken without a client decision):
 * - NO monetary fields anywhere. The only permitted wording about amounts is
 *   `SiteSettings.inquiryPolicy` (BUILD_SPEC §0.3.1) — nowhere else.
 * - Arabic-first: `ar` is always present. `en` / `zh` are included only where
 *   the source provides them. A missing `zh` means "fall back to `ar`" —
 *   never machine-translate (BUILD_SPEC §0.7, CI-09).
 * - A spec value missing in the source stays ABSENT (omit the row), never guessed.
 * - LM PACK is Shenzhen Kexin, NOT EFORE (xlsx attribution corrected; see
 *   products.ts). Brand attribution is otherwise verbatim from the xlsx.
 */

export type Locale = "ar" | "en" | "zh";

/**
 * Arabic-first localised string. `ar` is always present; `en` / `zh` only
 * where the source provides them. Missing `zh` = fall back to `ar`.
 */
export interface LocalizedString {
  ar: string;
  en?: string;
  zh?: string;
}

export type ProductStatus = "published" | "pending";
export type SourceStatus =
  | "confirmed"
  | "factory_catalog_verified"
  | "partial"
  | "awaiting_client_list";

export interface SpecRow {
  label: LocalizedString;
  value: string;
}

export interface Product {
  /** Catalogue id, p01..p39 (xlsx row number). */
  id: string;
  /** ASCII URL slug, derived from brand + model. */
  slug: string;
  brand: string;
  model: string;
  categoryId: CategoryId;
  subcategory: LocalizedString;
  name: LocalizedString;
  /**
   * Verbatim xlsx "المواصفات الرئيسية" (Arabic). Absent when the source has
   * no spec text at all (p11).
   */
  overview?: LocalizedString;
  /**
   * Only verbatim capability fragments from the xlsx spec text (rule: the
   * fragment states a capability — supports / expandable / suitable /
   * built-in / automatic / fire suppression / Bluetooth / Wi-Fi). Absent
   * when no fragment qualifies; never invented.
   */
  benefits?: LocalizedString[];
  /**
   * Identity rows (brand, model, category, subcategory) + one row per
   * verified xlsx spec fragment, verbatim. Missing values are ABSENT.
   */
  specs: SpecRow[];
  /**
   * Stand-in photo filename under /images/photos/ (carried over from the old
   * build's assets/img/photos/; files are NOT in v2 yet — see products.ts
   * header). Absent when no model/photo is confirmed (p30, p39).
   */
  image?: string;
  /** Round-robin "featured" selection — same rule as old build tools/build.py `_featured(12)`. */
  featured: boolean;
  status: ProductStatus;
  sourceStatus: SourceStatus;
  /** Internal traceability note from the xlsx (sanitised: any monetary sentence removed at extraction). Do not render as customer-facing copy. */
  sourceNote?: LocalizedString;
}

export type CategoryId =
  | "inverters"
  | "batteries"
  | "panels"
  | "pumps"
  | "controllers"
  | "systems"
  | "storage-ci"
  | "cameras";

export interface Category {
  id: CategoryId;
  name: LocalizedString;
  note: LocalizedString;
  icon: string;
  priority: "high" | "medium" | "low";
  /** Arabic subcategories, from xlsx sheet "ملخص الأقسام". */
  subcategories: string[];
  brands: string[];
  /** Computed from products.ts (published products in this category). */
  publishedCount: number;
}

export type BundleStatus = "confirmed" | "archived";

export interface Bundle {
  /** bundle-1..bundle-4. */
  id: string;
  slug: string;
  name: LocalizedString;
  /** Verbatim xlsx components (Arabic). */
  components: LocalizedString;
  /** Verbatim xlsx "الاستخدام المناسب" (Arabic). */
  use: LocalizedString;
  status: BundleStatus;
  /**
   * Catalogue links asserted ONLY where the component is an identified
   * product. Unconfirmed components are NOT linked (see bundles.ts).
   */
  componentProductIds: string[];
  /**
   * INTERNAL — open questions awaiting Ghamdan's answer (CI-03). Not
   * customer-facing copy.
   */
  openConfirmation?: LocalizedString;
}

export interface Agency {
  id: string;
  name: string;
  /** "وكيل رسمي في اليمن" (Deye only) / "علامة نوفرها". */
  status: LocalizedString;
  text: LocalizedString;
  /** true ONLY for Deye — "agent" status of the other brands is unproven (CI-04). */
  officialAgent: boolean;
  confirmationStatus: "confirmed" | "pending";
  productIds: string[];
}

export interface SolutionPillar {
  icon: string;
  title: LocalizedString;
  text: LocalizedString;
}

export interface SolutionArea {
  id: string;
  icon: string;
  pill: LocalizedString;
  title: LocalizedString;
  text: LocalizedString;
}

export interface ProcessStep {
  icon: string;
  title: LocalizedString;
  text: LocalizedString;
}

export interface Service {
  icon: string;
  title: LocalizedString;
  text: LocalizedString;
}

export interface PumpingStep {
  n: string;
  title: LocalizedString;
  text: LocalizedString;
}

export interface PumpingChallenge {
  icon: string;
  title: LocalizedString;
  text: LocalizedString;
}

export interface PumpingApplication {
  image: string;
  title: LocalizedString;
}

export interface PumpingDetail {
  id: "pumping";
  heroTitle: LocalizedString;
  heroCopy: LocalizedString;
  overviewTitle: LocalizedString;
  overviewHead: LocalizedString;
  overviewCopy: LocalizedString;
  overviewFeatures: { icon: string; title: LocalizedString }[];
  challengesTitle: LocalizedString;
  challenges: PumpingChallenge[];
  stepsTitle: LocalizedString;
  steps: PumpingStep[];
  diagramTitle: LocalizedString;
  diagramPill: LocalizedString;
  applicationsTitle: LocalizedString;
  applications: PumpingApplication[];
  ctaTitle: LocalizedString;
  /**
   * true: sizing / pump selection is guidance only (CI-14) — no specific
   * pump model is recommended by this content.
   */
  guidanceOnly: boolean;
}

/** One page's inline copy: keys k1..kN, verbatim from the old HTML inline `GTS_PAGE_I18N` JSON. */
export type PageCopy = Record<string, LocalizedString>;

export interface PagesCopy {
  home: PageCopy;
  about: PageCopy;
  solutions: PageCopy;
  catalog: PageCopy;
  projects: PageCopy;
  contact: PageCopy;
  category: Record<string, PageCopy>;
  productDetail: Record<string, PageCopy>;
  solutionDetail: Record<string, PageCopy>;
  projectDetail: Record<string, PageCopy>;
  services: PageCopy;
  support: PageCopy;
  news: PageCopy;
  agencies: { list: PageCopy; detail: Record<string, PageCopy> };
  systems: { list: PageCopy; bundles: Record<string, PageCopy> };
  downloads: PageCopy;
  legal: { privacy: PageCopy; terms: PageCopy };
  search: PageCopy;
  guidance: PageCopy;
  notFound: PageCopy;
}

export interface Project {
  id: string;
  slug: string;
  title: LocalizedString;
}

export interface SiteSettings {
  brand: {
    name: LocalizedString;
    short: string;
    latinName: string;
    tagline: LocalizedString;
    taglineMark: string;
    logoMode: "wordmark";
  };
  contact: {
    whatsapp: string;
    whatsappDisplay: string;
    whatsappUrl: string;
    phoneDisplay: string;
    email: string;
    address: LocalizedString;
    hours: LocalizedString;
  };
  social: {
    facebook: string;
    instagram: string;
  };
  /**
   * The ONLY permitted wording about amounts / availability (BUILD_SPEC
   * §0.3.1), in all three locales. Use this sentence wherever the site must
   * say how amounts are settled; never write another variant.
   */
  inquiryPolicy: LocalizedString;
  warranty: {
    status: "pending_client_approval";
    text: LocalizedString;
  };
}
